import{_ as e,o as t,c as d,ag as o}from"./chunks/framework.DyxC4IQh.js";const b=JSON.parse('{"title":"下载","description":"","frontmatter":{},"headers":[],"relativePath":"download.md","filePath":"download.md","lastUpdated":1792170324000}'),r={name:"download.md"};function s(i,a,l,c,h,n){return t(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h1><p>VimAct 通过本网站分发 APK。下载入口在本页，APK 文件和校验值放在站点仓库的 Releases 里。</p><p>系统要求：Android 10（API 29）及以上，配一把物理键盘。应用不区分 CPU 架构，不含原生库。</p><h2 id="两个渠道" tabindex="-1">两个渠道 <a class="header-anchor" href="#两个渠道" aria-label="Permalink to &quot;两个渠道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th>版本名</th><th>定位</th><th>发布条件</th></tr></thead><tbody><tr><td>正式版</td><td><code>0.1.0</code></td><td>日常可用</td><td>最高级别混淆构建 + 正式签名 + 真机验证通过</td></tr><tr><td>测试版</td><td><code>0.2.0-beta.1</code></td><td>提前尝新，随时可能坏</td><td>同样走混淆与签名，但不等真机验证结论</td></tr></tbody></table><p>两个渠道由同一把签名密钥签发，因此可以互相覆盖安装，不需要先卸载。版本名降级（例如从 <code>0.2.0-beta.1</code> 回到 <code>0.1.0</code>）系统会拒绝，那种情况需要先卸载再装。</p><p>版本号按语义化版本走，<code>MAJOR.MINOR.PATCH</code>，当前处于 <code>0.x</code> 阶段。测试版用 <code>-beta.N</code> 后缀。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>两个渠道都还没有可下载的构建。</p><p>卡住的是正式版发布条件。v0.1 至今只在 debug 构建上验证过，而 debug 包不混淆、用调试签名，不能作为发布物。发布前必须先落地 release 构建链：R8 全量模式、类与方法重命名、资源压缩、正式签名，然后装机跑一遍完整闭环。</p><p>这条门槛不会因为「先放个包上去」而放宽。混淆后的 release 构建在没有真机验证的情况下是未知量，把未知量发给用户比晚几天发布更糟。</p><h2 id="完整性校验" tabindex="-1">完整性校验 <a class="header-anchor" href="#完整性校验" aria-label="Permalink to &quot;完整性校验&quot;">​</a></h2><p>每个 APK 旁边都提供 SHA-256，列在对应 Release 的正文里。下载后核对：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sha256sum vimact-0.1.0-release.apk</span></span></code></pre></div><p>对不上就不要装。</p><h2 id="权限清单" tabindex="-1">权限清单 <a class="header-anchor" href="#权限清单" aria-label="Permalink to &quot;权限清单&quot;">​</a></h2><p>APK 不声明 <code>INTERNET</code>，也不声明任何其他 <code>uses-permission</code>。装机时系统显示的权限请求为空。</p><p>它能读屏幕和派发点击，全部来自你在系统设置里手动授予的无障碍服务，撤销随时生效。不申请录屏权限，不申请存储权限，不含第三方分析 SDK。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>拿到 APK 后用文件管理器打开安装，允许一次「来自此来源的应用」。装完必须去开无障碍服务，否则一切都不会发生，步骤见<a href="/vimact-site/guide/accessibility.html">启用无障碍服务</a>。</p><h2 id="关于自行构建" tabindex="-1">关于自行构建 <a class="header-anchor" href="#关于自行构建" aria-label="Permalink to &quot;关于自行构建&quot;">​</a></h2><p>源码当前未公开，暂时无法自行构建复现。这一点会随源码计划一起更新。</p>',22)])])}const u=e(r,[["render",s]]);export{b as __pageData,u as default};
